1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	
14	const DEDUCTIBLE_PER_DAMAGE = 100;
15	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
16	const REDUCED_REIMBURSEMENT_RATE = 0.5;
17	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
18	
19	const CURSE_SURCHARGE_RATE = 0.5;
20	
21	const HIGH_ENCHANTMENT_LEVEL = 5;
22	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
23	
24	const LOYALTY_YEARS = 2;
25	const LOYALTY_DISCOUNT_RATE = 0.2;
26	
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	
29	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
30	
31	const COMPONENT_BASE_PREMIUM = 25;
32	const COMPONENT_BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
34	
35	const COMPONENT_INSURANCE_VALUE = 250;
36	
37	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
38	  sword: 1000,
39	  amulet: 600,
40	  staff: 800,
41	  potion: 400,
42	};
43	
44	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	};
50	
51	const COMPONENT_TYPES = ["rune", "moonstone"];
52	
53	function isComponent(type: string): boolean {
54	  return COMPONENT_TYPES.includes(type);
55	}
56	
57	// The MHPCO insures only the items on its price list.
58	function isInsurable(type: string): boolean {
59	  return isComponent(type) || type in MAIN_ITEM_BASE_PREMIUMS;
60	}
61	
62	function requireInsurable(type: string): void {
63	  if (!isInsurable(type)) {
64	    throw new Error(`The MHPCO does not insure items of type ${type}`);
65	  }
66	}
67	
68	function itemBasePremium(type: string): number {
69	  requireInsurable(type);
70	  return isComponent(type) ? COMPONENT_BASE_PREMIUM : MAIN_ITEM_BASE_PREMIUMS[type];
71	}
72	
73	function countByType(items: Item[]): Map<string, number> {
74	  const counts = new Map<string, number>();
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	  return counts;
79	}
80	
81	// The MHPCO offers the building block on components. No active example prices a
82	// group of three alike main items, so the size test below is not yet qualified
83	// by `isComponent`; qualify it when such an example is activated.
84	function alikeGroupBasePremium(type: string, count: number): number {
85	  if (count === COMPONENT_BLOCK_SIZE) {
86	    return COMPONENT_BLOCK_BASE_PREMIUM;
87	  }
88	  return count * itemBasePremium(type);
89	}
90	
91	function policyBasePremium(items: Item[]): number {
92	  let total = 0;
93	  for (const [type, count] of countByType(items)) {
94	    total += alikeGroupBasePremium(type, count);
95	  }
96	  return total;
97	}
98	
99	// Which risk surcharges an item's own risk profile earns, as a combined rate.
100	function isHighlyEnchanted(item: Item): boolean {
101	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
102	}
103	
104	function itemSurchargeRate(item: Item): number {
105	  return (
106	    (item.cursed === true ? CURSE_SURCHARGE_RATE : 0) +
107	    (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0)
108	  );
109	}
110	
111	// Item-specific modifiers apply to the base premium of the affected item, not to
112	// the policy total.
113	function itemSurcharges(items: Item[]): number {
114	  return items.reduce(
115	    (total, item) => total + itemSurchargeRate(item) * itemBasePremium(item.type),
116	    0,
117	  );
118	}
119	
120	function isLongStanding(customer: Customer): boolean {
121	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
122	}
123	
124	// Which policy-wide modifiers the customer's standing earns, as a combined signed
125	// rate: discounts are negative, surcharges positive. The first-insurance surcharge
126	// is unconditional -- every quoted item is a first insurance, whatever the
127	// customer's history.
128	function policyWideRate(customer: Customer, precedingContracts: number): number {
129	  return (
130	    (isLongStanding(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
131	    FIRST_INSURANCE_SURCHARGE_RATE +
132	    (precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0)
133	  );
134	}
135	
136	// The MHPCO stages a premium: item-specific modifiers apply to the base premium
137	// of the affected item, policy-wide modifiers apply to the policy base premium,
138	// and the processing fee is added at the very end.
139	export function quote(customer: Customer, items: Item[], precedingContracts = 0): number {
140	  const basePremium = policyBasePremium(items);
141	  const premiumBeforeFee =
142	    basePremium +
143	    itemSurcharges(items) +
144	    // Policy-wide modifiers apply to the policy base premium, not to any single item.
145	    policyWideRate(customer, precedingContracts) * basePremium;
146	  return premiumBeforeFee + PROCESSING_FEE;
147	}
148	
149	export interface QuoteStep {
150	  op: "quote";
151	  items: Item[];
152	}
153	
154	export interface Damage {
155	  itemType: string;
156	  amount: number;
157	}
158	
159	export interface Incident {
160	  cause: string;
161	  damages: Damage[];
162	}
163	
164	export interface ClaimStep {
165	  op: "claim";
166	  policy: number;
167	  incident: Incident;
168	}
169	
170	export type Step = QuoteStep | ClaimStep;
171	
172	export interface Scenario {
173	  customer: Customer;
174	  steps: Step[];
175	}
176	
177	export interface QuoteResult {
178	  premium: number;
179	}
180	
181	export interface ClaimResult {
182	  payout: number;
183	  remainingCap: number;
184	}
185	
186	export type StepResult = QuoteResult | ClaimResult;
187	
188	// The MHPCO insures each item at its price-list insurance value; the block
189	// discount affects the premium only, not the insurance sum.
190	function itemInsuranceValue(type: string): number {
191	  requireInsurable(type);
192	  return isComponent(type) ? COMPONENT_INSURANCE_VALUE : MAIN_ITEM_INSURANCE_VALUES[type];
193	}
194	
195	function insuranceSum(items: Item[]): number {
196	  return items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
197	}
198	
199	// A policy the MHPCO has written: the items it covers and the payout cap still
200	// available on it.
201	interface Policy {
202	  items: Item[];
203	  remainingCap: number;
204	}
205	
206	const FULL_REIMBURSEMENT_RATE = 1;
207	
208	// The share of a damage the MHPCO reimburses, arbitrating both of its clauses:
209	// damage to a highly enchanted item earns half the damage amount, and damage to
210	// an item of dragon material is fully reimbursed. The 50 % clause wins wherever
211	// both apply, and full reimbursement is what the MHPCO grants anyway, so dragon
212	// material never moves the rate and the decision turns on enchantment alone.
213	function reimbursementRate(item: Item): number {
214	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
215	    ? REDUCED_REIMBURSEMENT_RATE
216	    : FULL_REIMBURSEMENT_RATE;
217	}
218	
219	// The MHPCO reimburses a damage at the rate its item's clauses earn, less the
220	// deductible that applies to every damage event.
221	// A damage that does not exceed the deductible earns nothing; the MHPCO never
222	// pays out a negative amount.
223	function damagePayout({ item, damage }: DamageToInsuredItem): number {
224	  return Math.max(0, reimbursementRate(item) * damage.amount - DEDUCTIBLE_PER_DAMAGE);
225	}
226	
227	// The MHPCO rounds in its own favour: a payout is rounded down.
228	function roundedPayout(payout: number): number {
229	  return Math.floor(payout);
230	}
231	
232	// The MHPCO writes a policy over the quoted items and opens its payout cap at
233	// twice the insurance sum.
234	function writePolicy(items: Item[]): Policy {
235	  return {
236	    items,
237	    remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items),
238	  };
239	}
240	
241	// A damage report the MHPCO has accepted: the reported damage together with the
242	// one insured item it is charged against.
243	interface DamageToInsuredItem {
244	  item: Item;
245	  damage: Damage;
246	}
247	
248	// A damage report the MHPCO will not consider at all. Damage is a loss, so a
249	// report of a negative amount is not a claim the MHPCO can assess.
250	function requireReportableDamage(damage: Damage): void {
251	  if (damage.amount < 0) {
252	    throw new Error(`A damage amount cannot be negative: ${String(damage.amount)}`);
253	  }
254	}
255	
256	// Which insured item each damage report is charged against. The MHPCO only
257	// reimburses damage to an item its policy actually covers, and every damage is a
258	// damage to one insured item, so each report claims a distinct item of its type:
259	// a policy cannot be claimed for more items than it covers.
260	function damagesToInsuredItems(policy: Policy, damages: Damage[]): DamageToInsuredItem[] {
261	  const unclaimed = [...policy.items];
262	  return damages.map((damage) => {
263	    requireReportableDamage(damage);
264	    const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
265	    if (index === -1) {
266	      throw new Error(`The policy does not cover a further item of type ${damage.itemType}`);
267	    }
268	    return { item: unclaimed.splice(index, 1)[0], damage };
269	  });
270	}
271	
272	// What the MHPCO owes for an incident: every damage reimbursed in turn against
273	// its own insured item, the total rounded in the MHPCO's favour.
274	function claimPayout(policy: Policy, incident: Incident): number {
275	  return roundedPayout(
276	    damagesToInsuredItems(policy, incident.damages).reduce(
277	      (total, charged) => total + damagePayout(charged),
278	      0,
279	    ),
280	  );
281	}
282	
283	// A payout consumes the policy's cap, so successive claims on one policy
284	// accumulate against the same remaining cap.
285	function drawDownCap(policy: Policy, payout: number): number {
286	  policy.remainingCap -= payout;
287	  return policy.remainingCap;
288	}
289	
290	// The total payout per policy is capped at twice the insurance sum, so the MHPCO
291	// never pays out more than the cap the policy has left: a claim that asks for
292	// more is reduced to the remainder, and once the cap is exhausted it earns
293	// nothing.
294	function limitedToRemainingCap(policy: Policy, owed: number): number {
295	  return Math.min(owed, policy.remainingCap);
296	}
297	
298	// What the MHPCO settles for an incident: the amount the damages earn, limited to
299	// the policy's remaining cap, and drawn down from it.
300	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
301	  const payout = limitedToRemainingCap(policy, claimPayout(policy, incident));
302	  return { payout, remainingCap: drawDownCap(policy, payout) };
303	}
304	
305	// The MHPCO rounds in its own favour: a premium is rounded up, and only the
306	// final amount is rounded -- intermediate amounts stay fractional.
307	function roundedPremium(premium: number): number {
308	  return Math.ceil(premium);
309	}
310	
311	// Only a quote writes a contract. A claim is settled against a contract the
312	// MHPCO already holds, so it does not move the customer towards the follow-up
313	// contract discount.
314	function writesContract(step: Step): step is QuoteStep {
315	  return step.op === "quote";
316	}
317	
318	// A scenario is one customer's sequence of operations, processed in order. Each
319	// step is quoted against the number of contracts that preceded it, so every
320	// contract after the customer's first earns the follow-up-contract discount.
321	export function runScenario(scenario: Scenario): { results: StepResult[] } {
322	  const results: StepResult[] = [];
323	  const policies = new Map<number, Policy>();
324	  let precedingContracts = 0;
325	  scenario.steps.forEach((step, index) => {
326	    if (writesContract(step)) {
327	      results.push({
328	        premium: roundedPremium(quote(scenario.customer, step.items, precedingContracts)),
329	      });
330	      policies.set(index, writePolicy(step.items));
331	      precedingContracts += 1;
332	    } else {
333	      const policy = policies.get(step.policy);
334	      if (policy === undefined) {
335	        throw new Error(`Claim refers to step ${String(step.policy)}, which wrote no policy`);
336	      }
337	      results.push(settleClaim(policy, step.incident));
338	    }
339	  });
340	  return { results };
341	}
