1	#!/usr/bin/env node
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	// The claim-office CLI translates between the MHPCO's JSON documents and its
5	// domain operations: a scenario arrives on stdin and its results leave on
6	// stdout. A rejected scenario is reported on stderr with a non-zero exit code.
7	function readStdin(): Promise<string> {
8	  return new Promise((resolve, reject) => {
9	    let document = "";
10	    process.stdin.setEncoding("utf8");
11	    process.stdin.on("data", (chunk: string) => (document += chunk));
12	    process.stdin.on("end", () => {
13	      resolve(document);
14	    });
15	    process.stdin.on("error", reject);
16	  });
17	}
18	
19	async function main(): Promise<void> {
20	  const scenario = JSON.parse(await readStdin()) as Scenario;
21	  process.stdout.write(JSON.stringify(runScenario(scenario)));
22	}
23	
24	main().catch((reason: unknown) => {
25	  process.stderr.write(`${reason instanceof Error ? reason.message : String(reason)}\n`);
26	  process.exitCode = 1;
27	});
