1	import { execFileSync } from "node:child_process";
2	import { describe, expect, it } from "vitest";
3	import { quote, runScenario } from "./claim-office.js";
4	
5	// Observable contract readings adopted where the specification leaves them open:
6	// - The specification defines rejection only at the CLI level ("exits with a
7	//   non-zero status code and writes an error description to stderr"). The most
8	//   defensible reading is that the domain layer signals rejection by throwing an
9	//   Error, and the CLI adapter translates a thrown Error into exit code 1 plus a
10	//   stderr message. Tests below state which layer they observe.
11	// - "A building block of 3 alike components" is read, per the spec examples, as
12	//   exactly-3 groups of the identical component type (4 runes => no block).
13	
14	describe("MHPCO Claim Office", () => {
15	  // --- Quote: processing fee and the item catalogue ---
16	  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
17	    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
18	  });
19	  it("quotes a single plain sword as premium 105 G (100 G base + 5 G fee)", () => {
20	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
21	  });
22	  it("quotes a single plain amulet as premium 65 G (60 G base + 5 G fee)", () => {
23	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
24	  });
