54	  it("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types) -- premium 80 G", () => {
55	    expect(
56	      quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }]),
57	    ).toBe(87.5);
