59	  it("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks) -- premium 125 G", () => {
60	    expect(
61	      quote({ yearsWithMHPCO: 0 }, [
62	        ...Array(3).fill({ type: "rune" }),
