97	  it("applies the 10 % first-insurance surcharge to a newcomer's first quote: sword, 0 years => 100 + 10 + 5 = 115 G", () => {
98	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
