130	    expect(results[0]).toEqual({ premium: 198 });
131	  });
132	  it("keeps intermediate amounts fractional and rounds only the final premium: a single rune computes 32.5 G and is reported as 33 G", () => {
133	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(32.5);
134	    const { results } = runScenario({
135	      customer: { yearsWithMHPCO: 0 },
136	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
137	    });
138	    expect(results[0]).toEqual({ premium: 33 });
139	  });
140	
141	  // --- Quote: integration examples ---
142	  it("integration: newcomer (0 years, no previous contract) with a cursed steel sword (ench. 3) => premium 165 G", () => {
143	    const { results } = runScenario({
144	      customer: { yearsWithMHPCO: 0 },
145	      steps: [
146	        {
147	          op: "quote",
148	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
149	        },
150	      ],
151	    });
152	    expect(results[0]).toEqual({ premium: 165 });
153	  });
154	  it("integration: 3-year customer's second quote with a cursed steel sword (ench. 7) => premium 160 G", () => {
155	    const cursedSword = { type: "sword", material: "steel", enchantment: 7, cursed: true };
156	    const { results } = runScenario({
157	      customer: { yearsWithMHPCO: 3 },
158	      steps: [
159	        { op: "quote", items: [cursedSword] },
160	        { op: "quote", items: [cursedSword] },
161	      ],
162	    });
163	    expect(results[1]).toEqual({ premium: 160 });
164	  });
165	
166	  // --- Quote: rejection ---
167	  it("rejects a quote containing an unknown item type (e.g. broomstick) by throwing an Error (CLI: non-zero exit, error on stderr, no results on stdout)", () => {
168	    expect(() =>
169	      runScenario({
170	        customer: { yearsWithMHPCO: 0 },
171	        steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
172	      }),
