new='''// The policies a scenario has written so far, each filed under the index of the
// quote step that wrote it. A claim names its policy by that index, so a claim
// against a step that wrote none is a claim the MHPCO cannot place.
class WrittenPolicies {
  private readonly byStep = new Map<number, Policy>();

  file(step: number, policy: Policy): void {
    this.byStep.set(step, policy);
  }

  named(step: number): Policy {
    const policy = this.byStep.get(step);
    if (policy === undefined) {
      throw new Error(`Claim refers to step ${String(step)}, which wrote no policy`);
    }
    return policy;
  }
}

// A scenario is one customer's sequence of operations, processed in order. Each
// step is quoted against the number of contracts that preceded it, so every
// contract after the customer's first earns the follow-up-contract discount.
export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const policies = new WrittenPolicies();
  let precedingContracts = 0;
  const results = scenario.steps.map((step, index): StepResult => {
    if (!writesContract(step)) {
      return settleClaim(policies.named(step.policy), step.incident);
    }
    const premium = roundedPremium(quote(scenario.customer, step.items, precedingContracts));
    policies.file(index, writePolicy(step.items));
    precedingContracts += 1;
    return { premium };
  });
  return { results };
}
'''
